"""Generate non-deployable V1.1 schema examples. Not used by robot runtime."""
from pathlib import Path
import csv, json, hashlib, yaml
P=Path(__file__).resolve().parents[1]
S=P/'schemas'; E=P/'examples'
S.mkdir(exist_ok=True); E.mkdir(exist_ok=True)
hash_={'type':'string','pattern':'^[a-f0-9]{64}$'}
fileref={'type':'object','additionalProperties':False,'required':['path','sha256'],'properties':{'path':{'type':'string','minLength':1},'sha256':hash_}}
tensor={'type':'object','additionalProperties':False,'required':['name','dtype','shape','semantic'],'properties':{'name':{'type':'string','minLength':1},'dtype':{'enum':['FLOAT32','FLOAT16','INT8','INT32']},'shape':{'type':'array','minItems':1,'items':{'type':'integer','minimum':1}},'semantic':{'type':'string','minLength':1}}}
guard={'type':'object','additionalProperties':False,'required':['predicates','max_duration_ms'],'properties':{'predicates':{'type':'array','items':{'type':'string'}},'max_duration_ms':{'type':'integer','minimum':1},'stable_ms':{'type':'integer','minimum':0}}}
action_graph={'$schema':'https://json-schema.org/draft/2020-12/schema','title':'Collie ActionGraph V1.1','type':'object','additionalProperties':False,'required':['schema_version','nodes','edges'],'properties':{'schema_version':{'const':'1.1'},'nodes':{'type':'array','minItems':1,'uniqueItems':True,'items':{'type':'string','pattern':'^[a-z][a-z0-9_]*$'}},'edges':{'type':'array','items':{'type':'object','additionalProperties':False,'required':['from','to','cost','guard','max_duration_ms','on_timeout'],'properties':{'from':{'type':'string'},'to':{'type':'string'},'cost':{'type':'integer','minimum':0},'guard':{'type':'array','minItems':1,'items':{'type':'string'}},'max_duration_ms':{'type':'integer','minimum':1},'on_timeout':{'enum':['DAMPING','ESTOP','PHASE_FALLBACK','SAFE_HOLD_IF_VERIFIED']}}}}}}
runner_manifest={'$schema':'https://json-schema.org/draft/2020-12/schema','title':'Collie RunnerManifest V1.1','type':'object','additionalProperties':False,'required':['schema_version','manifest_id','version','action_id','behavior_id','robot_compatibility','runner','asset','tensor_io','obs_spec','action_spec','owns','entry','exit','completion','failure_target','golden','release'],'properties':{'schema_version':{'const':'1.1'},'manifest_id':{'type':'string','minLength':1},'version':{'type':'string','pattern':'^\\d+\\.\\d+\\.\\d+$'},'action_id':{'type':'string','minLength':1},'behavior_id':{'type':'string','minLength':1},'robot_compatibility':{'type':'object','additionalProperties':False,'required':['robot_ids','topology_sha256','calibration_sha256'],'properties':{'robot_ids':{'type':'array','minItems':1,'items':{'type':'string'}},'topology_sha256':hash_,'calibration_sha256':hash_}},'runner':{'type':'object','additionalProperties':False,'required':['class_id','execution_kind','behavior_role','backend_id','abi_version','period_ms','worker_budget_ms'],'properties':{'class_id':{'enum':['RlLocomotionRunner','WheelDriveRunner','TransitionRunner','BalanceRunner','ClassicalPoseRunner','RecoveryRunner','PlaybackRunner','OverlayRunner']},'execution_kind':{'enum':['ONNX','CLASSICAL','PLAYBACK','COMPOSITE']},'behavior_role':{'enum':['LOCOMOTION','TRANSITION','BALANCE','POSE','RECOVERY','OVERLAY']},'backend_id':{'type':'string','minLength':1},'abi_version':{'type':'string','minLength':1},'period_ms':{'type':'integer','minimum':1},'worker_budget_ms':{'type':'number','exclusiveMinimum':0}}},'asset':{'type':'object','additionalProperties':False,'required':['kind'],'properties':{'kind':{'enum':['MODEL','TRAJECTORY','BUILTIN']},'path':{'type':'string','minLength':1},'sha256':hash_},'allOf':[{'if':{'properties':{'kind':{'enum':['MODEL','TRAJECTORY']}},'required':['kind']},'then':{'required':['path','sha256']}}]},'tensor_io':{'type':'object','additionalProperties':False,'required':['inputs','outputs'],'properties':{'inputs':{'type':'array','items':tensor},'outputs':{'type':'array','items':tensor}}},'obs_spec':fileref,'action_spec':fileref,'owns':{'type':'array','minItems':1,'uniqueItems':True,'items':{'type':'string'}},'entry':guard,'exit':guard,'completion':guard,'failure_target':{'enum':['DAMPING','ESTOP','PHASE_FALLBACK','SAFE_HOLD_IF_VERIFIED']},'golden':fileref,'release':{'type':'object','additionalProperties':False,'required':['status','release_id'],'properties':{'status':{'enum':['DISABLED','CANDIDATE','APPROVED']},'release_id':{'type':'string','minLength':1}}}}}
obs_cols=['tensor_name','index','block','element','source','source_field','joint_or_axis','unit','frame','transform','offset','scale','clip_min','clip_max','filter_id','history_lag','history_order','include_current','initial_fill','missing_policy_ref','dtype']
action_cols=['tensor_name','tensor_index','joint_name','mode','unit','scale','default','raw_clip_min','raw_clip_max','activation','kp','kd','tau_ff','limit_profile','owns','sign']
def row_schema(cols,props):
 return {'$schema':'https://json-schema.org/draft/2020-12/schema','type':'object','additionalProperties':False,'required':cols,'properties':props}
nonempty={'type':'string','minLength':1}
obs_props={k:nonempty for k in obs_cols}
obs_props.update(index={'type':'integer','minimum':0},element={'type':'integer','minimum':0},offset={'type':'number'},scale={'type':'number'},clip_min={'type':'number'},clip_max={'type':'number'},history_lag={'type':'integer','minimum':0},include_current={'type':'boolean'},transform={'enum':['IDENTITY','CENTER_SCALE_CLIP','SCALE_CLIP','ANGLE_WRAP_SCALE_CLIP','QUAT_TO_GRAVITY_SCALE_CLIP']},history_order={'enum':['OLDEST_TO_NEWEST','NEWEST_TO_OLDEST']},initial_fill={'enum':['REPEAT_FIRST','ZEROS','REFERENCE','ASSET']},dtype={'enum':['FLOAT32','FLOAT16','INT8','INT32']})
action_props={k:nonempty for k in action_cols}
action_props.update(tensor_index={'type':'integer','minimum':0},scale={'type':'number','minimum':0},default={'type':'number'},raw_clip_min={'type':'number'},raw_clip_max={'type':'number'},kp={'type':'number','minimum':0},kd={'type':'number','minimum':0},tau_ff={'type':'number'},owns={'type':'boolean'},sign={'enum':[-1,1]},mode={'enum':['POSITION','VELOCITY','TORQUE']},activation={'enum':['IDENTITY','TANH']})
for name, schema in [('action_graph.schema.json',action_graph),('runner_manifest.schema.json',runner_manifest),('obs_spec.row.schema.json',row_schema(obs_cols,obs_props)),('action_spec.row.schema.json',row_schema(action_cols,action_props))]:
 (S/name).write_text(json.dumps(schema,indent=2,ensure_ascii=False)+'\n')

names=[f'{leg}_{j}' for leg in ['fl','fr','rl','rr'] for j in ['hip','thigh','calf']]+[f'{leg}_wheel' for leg in ['fl','fr','rl','rr']]
with (E/'demo16_obsspec.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,obs_cols);w.writeheader()
 for i,name in enumerate(names):
  w.writerow(dict(tensor_name='demo_obs',index=i,block='joint_position',element=i,source='joints',source_field='q',joint_or_axis=name,unit='rad',frame='joint',transform='CENTER_SCALE_CLIP',offset='0.0',scale='1.0',clip_min='-100.0',clip_max='100.0',filter_id='none',history_lag=0,history_order='OLDEST_TO_NEWEST',include_current='true',initial_fill='REPEAT_FIRST',missing_policy_ref='STRICT_INVALID',dtype='FLOAT32'))
with (E/'demo16_actionspec.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,action_cols);w.writeheader()
 for i,name in enumerate(names):
  wheel=name.endswith('_wheel')
  w.writerow(dict(tensor_name='demo_act',tensor_index=i,joint_name=name,mode='VELOCITY' if wheel else 'POSITION',unit='rad/s' if wheel else 'rad',scale=1.0,default=0.0,raw_clip_min=-1.0,raw_clip_max=1.0,activation='IDENTITY',kp=0.0 if wheel else 10.0,kd=0.0 if wheel else 1.0,tau_ff=0.0,limit_profile='demo_wheel_limit' if wheel else 'demo_leg_limit',owns='true',sign=-1 if name=='fr_hip' else 1))

# Additional deliberately unsigned, non-deployable schema example. The hashes
# refer to files in this example bundle, not to any production model.
(E/'demo16_model.placeholder').write_text('NON-DEPLOYABLE demo16 tensor mapping fixture. This is not an ONNX model.\n')
(E/'demo16_golden.placeholder').write_text('NON-DEPLOYABLE golden placeholder. Not a valid golden test.\n')
sha=lambda x:hashlib.sha256((E/x).read_bytes()).hexdigest()
manifest={'schema_version':'1.1','manifest_id':'demo16_locomotion','version':'1.1.0','action_id':'demo16_loco','behavior_id':'demo16_loco','robot_compatibility':{'robot_ids':['demo16_nonphysical'],'topology_sha256':'a'*64,'calibration_sha256':'b'*64},'runner':{'class_id':'RlLocomotionRunner','execution_kind':'ONNX','behavior_role':'LOCOMOTION','backend_id':'onnxruntime_cpu','abi_version':'1','period_ms':10,'worker_budget_ms':7.6},'asset':{'kind':'MODEL','path':'demo16_model.placeholder','sha256':sha('demo16_model.placeholder')},'tensor_io':{'inputs':[{'name':'demo_obs','dtype':'FLOAT32','shape':[1,16],'semantic':'joint_positions'}],'outputs':[{'name':'demo_act','dtype':'FLOAT32','shape':[1,16],'semantic':'joint_commands'}]},'obs_spec':{'path':'demo16_obsspec.csv','sha256':sha('demo16_obsspec.csv')},'action_spec':{'path':'demo16_actionspec.csv','sha256':sha('demo16_actionspec.csv')},'owns':names,'entry':{'predicates':['feedback_fresh','form_quad','support_valid'],'max_duration_ms':1000},'exit':{'predicates':['speed_stable','support_valid'],'max_duration_ms':2000,'stable_ms':100},'completion':{'predicates':['stable'],'max_duration_ms':2000,'stable_ms':100},'failure_target':'DAMPING','golden':{'path':'demo16_golden.placeholder','sha256':sha('demo16_golden.placeholder')},'release':{'status':'CANDIDATE','release_id':'demo16-1.1.0-NOT-DEPLOYABLE'}}
(E/'demo16_runner_manifest.yaml').write_text(yaml.safe_dump(manifest,allow_unicode=True,sort_keys=False))
graph={'schema_version':'1.1','nodes':['quad_stand','quad_drive','quad_stop','q2b','biped_balance','b2q'],'edges':[{'from':'quad_drive','to':'quad_stop','cost':1,'guard':['feedback_fresh'],'max_duration_ms':1500,'on_timeout':'DAMPING'},{'from':'quad_stop','to':'q2b','cost':3,'guard':['support_valid','clearance_token_fresh'],'max_duration_ms':2000,'on_timeout':'DAMPING'}]}
(E/'action_graph.yaml').write_text(yaml.safe_dump(graph,allow_unicode=True,sort_keys=False))
(P/'safety_limits.yaml').write_text('schema_version: "1.1"\nrobot_id: demo16_nonphysical\nrelease_approved: false\nphysical_limits_signed: false\nmissing_policies:\n  STRICT_INVALID: {on_missing: INVALIDATE_SNAPSHOT}\nlimit_profiles:\n  demo_leg_limit: {approved: false}\n  demo_wheel_limit: {approved: false}\n# No physical limit values are approved. This file MUST fail motion admission.\n')
